__GUILE_LOAD_PATH="\"${MES_PREFIX}/mes/module:${MES_PREFIX}/module:/nix/store/d2sn1b4i5r4hlz0sy039cb2y88pr7ga5-nyacc-1.09.1/share/nyacc-1.09.1/module\""
